       "x": "方法地图大致分七类：形成性研究（访谈、观察、日记法，一到四周）、评估性研究（可用性测试、走查、启发式评估，两天到两周）、结构与分类（卡片分类、树测试）、快速验证（五秒测试、假门、原型测试、A/B）、规模化（问卷、埋点、会话回放、搜索日志）、无障碍与特殊人群研究、研究运营（招募、知情同意、记录分析与汇报）。选方法有两个判据。一是**成本与风险匹配**：低风险、可回滚的改动配便宜方法，专家评审和五秒测试就够；高风险、不可逆的决策（定价、核心流程、合规）要更严谨的方法和更大样本。二是**由便宜到贵**：专家评审、游击测试、正式可用性测试、A/B 与大样本量化，前一环能定位并修掉问题，就不必进下一环。"
