       "x": "季度初，团队排出路线图：一页纸、十几条功能、每条都有上线月份。销售把截图发给客户，客户据此排了门店物料和一次大促。两个月后，一条支付依赖被合规评审拖住，功能延后三周。续约会上客户第一句话是「你们上次也这么说」。问题不在延后——路线图本来就会变；问题在于**把计划写成了承诺**。路线图真正的用途不是让未来确定，而是让团队在资源有限时**对做什么、先做什么、放弃什么达成共识**。一旦它被当成合同，团队就会为了守日期做错事：不敢砍、不敢承认没想清楚、把该做的验证挪到上线之后。"
