       "x": "留存不是一个数字，而是同一批用户在第 2、7、30 天回访的比例，按批次（cohort）画成曲线。判断三种形态：**一路归零**，价值还没成立，先修激活与核心体验，别放量；**在某个水平走平**，有一批核心用户持续获得价值，PMF 有初步证据，下一步弄清「谁留下、因为什么」；**走平后回升**，多半来自召回或推送，要分辨是价值回流还是一次性刺激，看停掉触达后会不会回落。读曲线前先固定口径、批次与时间窗——口径不同的「留存率」不能比。"
